import os, re

def run(**kwargs):
    path = kwargs.get('path', '')
    pattern = kwargs.get('pattern', '')
    is_regex = bool(kwargs.get('is_regex', False))
    context_bytes = int(kwargs.get('context_bytes', 400))
    max_matches = int(kwargs.get('max_matches', 20))
    max_file_mb = float(kwargs.get('max_file_mb', 500))
    op = kwargs.get('op', 'find')

    if op == 'ls':
        out = []
        if os.path.isfile(path):
            out.append(f"{os.path.getsize(path):>12}  {path}")
        else:
            for root, dirs, files in os.walk(path):
                for f in files:
                    fp = os.path.join(root, f)
                    try:
                        sz = os.path.getsize(fp)
                    except OSError:
                        sz = -1
                    out.append(f"{sz:>12}  {fp}")
            out.sort()
        return f"{len(out)} files:\n" + "\n".join(out)

    if not pattern:
        return "ERROR: pattern required for op=find"
    try:
        rx = re.compile(pattern if is_regex else re.escape(pattern), re.DOTALL)
    except re.error as e:
        return f"ERROR: bad regex: {e}"

    def scan_file(fp):
        try:
            sz = os.path.getsize(fp)
        except OSError:
            return []
        if sz > max_file_mb * 1024 * 1024:
            return []
        try:
            with open(fp, 'rb') as fh:
                data = fh.read()
        except OSError:
            return []
        text = data.decode('utf-8', errors='replace')
        hits = []
        for m in rx.finditer(text):
            s, e = m.start(), m.end()
            cs = max(0, s - context_bytes)
            ce = min(len(text), e + context_bytes)
            ctx = text[cs:ce].replace('\n', '\\n').replace('\r', '')
            hits.append({
                "file": fp,
                "offset": s,
                "match": m.group(0)[:200],
                "context": ctx
            })
            if len(hits) >= max_matches:
                break
        return hits

    results = []
    files_searched = 0
    if os.path.isfile(path):
        files_searched = 1
        results = scan_file(path)
    else:
        for root, dirs, files in os.walk(path):
            for f in files:
                fp = os.path.join(root, f)
                files_searched += 1
                results.extend(scan_file(fp))
                if len(results) >= max_matches:
                    break
            if len(results) >= max_matches:
                break

    import json
    return json.dumps({
        "pattern": pattern,
        "files_searched": files_searched,
        "total_hits": len(results),
        "matches": results
    }, ensure_ascii=False, indent=1)

