import os

def run(**kwargs):
    path = kwargs.get('path', 'missions/duskyr.com/extractions')
    min_kb = float(kwargs.get('min_kb', 100))
    out = []
    for root, dirs, files in os.walk(path):
        for f in files:
            fp = os.path.join(root, f)
            try:
                sz = os.path.getsize(fp)
            except OSError:
                continue
            if sz >= min_kb * 1024:
                out.append((sz, fp))
    out.sort(reverse=True)
    return "\n".join(f"{sz:>10}  {fp}" for sz, fp in out[:40]) or f"no files >= {min_kb}KB"

